<div class="section-heading"><div><div class="eyebrow">Operação</div><h1>Estoque</h1><p class="text-secondary mb-0">Entradas, saídas, ajustes, histórico e alertas de estoque mínimo.</p></div></div>
<div class="row g-4"><div class="col-lg-4"><div class="card"><div class="card-body"><h2 class="h5">Movimentar estoque</h2><form method="post" action="/stock/adjust" class="d-grid gap-2"><?=
\App\Core\CSRF::field()?><select class="form-select" name="product_id" required><option value="">Produto</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?> · <?=number_format((float)$p['stock'],2,',','.')?></option><?php endforeach;?></select><select class="form-select" name="type"><option value="entry">Entrada</option><option value="exit">Saída</option><option value="adjustment">Ajuste +/-</option></select><input class="form-control" name="quantity" type="number" step=".001" required placeholder="Quantidade"><input class="form-control" name="reason" required placeholder="Motivo"><button class="btn btn-primary">Registrar</button></form></div></div></div><div class="col-lg-8"><div class="card"><div class="card-header"><strong>Posição atual</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Produto</th><th>Saldo</th><th>Mínimo</th><th>Status</th></tr></thead><tbody><?php foreach($products as $p):$low=(float)$p['stock']<=(float)$p['minimum_stock'];?><tr><td><?=htmlspecialchars($p['name'])?></td><td><?=number_format((float)$p['stock'],3,',','.')?> <?=htmlspecialchars($p['unit'])?></td><td><?=number_format((float)$p['minimum_stock'],3,',','.')?></td><td><span class="badge text-bg-<?=$low?'warning':'success'?>"><?=$low?'Estoque baixo':'OK'?></span></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<div class="card mt-4"><div class="card-header"><strong>Histórico de movimentos</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Quantidade</th><th>Saldo</th><th>Motivo</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=date('d/m/Y H:i',strtotime($m['created_at']))?></td><td><?=htmlspecialchars($m['product_name'])?></td><td><?=htmlspecialchars($m['type'])?></td><td><?=number_format((float)$m['quantity'],3,',','.')?></td><td><?=number_format((float)$m['balance_after'],3,',','.')?></td><td><?=htmlspecialchars($m['reason']??'')?></td></tr><?php endforeach;?></tbody></table></div></div>
